using UnityEngine;
using System;

namespace Gamejam.Core
{
    /// <summary>
    /// Data structure representing a noise event that can alert enemies.
    /// Noise is generated by player actions like dashing, landing, etc.
    /// </summary>
    public class NoiseEvent
    {
        /// <summary>Position where the noise was generated</summary>
        public Vector3 Position { get; set; }

        /// <summary>Priority level of the noise (higher = more important for enemies)</summary>
        public int Priority { get; set; }

        /// <summary>Type of noise for gameplay purposes (e.g., "Dash", "Run", "Land")</summary>
        public string NoiseType { get; set; }

        /// <summary>Radius within which entities can detect this noise</summary>
        public float DetectionRadius { get; set; }

        public NoiseEvent(Vector3 position, int priority, string noiseType, float detectionRadius = 50f)
        {
            Position = position;
            Priority = priority;
            NoiseType = noiseType;
            DetectionRadius = detectionRadius;
        }
    }

    /// <summary>
    /// Global event system for noise generation.
    /// Allows player actions to emit noise that enemies can detect.
    /// </summary>
    public static class NoiseGenerator
    {
        public static event Action<NoiseEvent> OnNoiseGenerated;

        /// <summary>Generate a noise event at the specified position</summary>
        public static void GenerateNoise(NoiseEvent noiseEvent)
        {
            OnNoiseGenerated?.Invoke(noiseEvent);
        }

        /// <summary>Convenience method to generate noise with standard parameters</summary>
        public static void GenerateNoise(Vector3 position, int priority, string noiseType)
        {
            var noiseEvent = new NoiseEvent(position, priority, noiseType);
            OnNoiseGenerated?.Invoke(noiseEvent);
        }
    }
}
